var m = tree.current_scene
var cc = m.charge_controller
if str(cc.active_unit_id) != "U_BATTLEWAGON_G":
	for i in range(cc.unit_selector.item_count):
		if str(cc.unit_selector.get_item_metadata(i)) == "U_BATTLEWAGON_G":
			cc.unit_selector.select(i)
			cc.unit_selector.item_selected.emit(i)
			break
return str(cc.active_unit_id)

var labels = []
for chip in PadHintBar._row.get_children():
	for l in chip.find_children("*", "Label", true, false):
		labels.append(l.text)
return "Snap to Contact" in labels

